tool_input.command:
node --input-type=module <<'EOF'
import { readFileSync } from "node:fs";
import { carve } from "./carve.js";
const src = readFileSync("game.package.js", "utf8");
const body = src.slice(src.indexOf("export function gameStep"), src.indexOf("export const gameRuntime")).replace("export ", "");
const fixed = new Function("IDLE", body + "return gameStep;")({ up: false, down: false, left: false, right: false });
// original rule: every tick on the exit counts
const original = (s, c) => fixed({ ...s, cleared: false }, c);
const control = (m, p) => { m.dx = p.right ? 1 : p.left ? -1 : 0; m.dy = p.down ? 1 : p.up ? -1 : 0; };
// stand-in for the host and run: ticks at k/30, host reads depth every 3 ticks, new cave from the next tick
function play(step, release) {
  let s = { t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1], cleared: false }, cave = 0; const log = [];
  for (let k = 0; k <= 45; k++) {
    const l = carve(7, cave, 45), before = s.depth;
    s = step(s, { dt: 1 / 30, kernels: { control }, controls: { pad: { right: k >= 1 && k < release } }, inputs: { start: [l.start.x, l.start.y], exit: [l.exit.x, l.exit.y] } });
    if (s.depth !== before) log.push(`k=${k} x=${s.miner.x} depth=${s.depth}`);
    if (k % 3 === 0) cave = s.depth;
  }
  return `final ${s.depth} [${log.join("; ")}]`;
}
console.log("release 7.5 original:", play(original, 8));
console.log("release 7.5 fixed:   ", play(fixed, 8));
console.log("held, original:      ", play(original, 99));
console.log("held, fixed:         ", play(fixed, 99));
for (const d of [0,1,2,3]) console.log("depth", d, JSON.stringify({ s: carve(7,d,45).start, e: carve(7,d,45).exit }));
console.log("45 vs 46 same level at depth 3:", JSON.stringify(carve(7,3,45)) === JSON.stringify(carve(7,3,46)));
EOF
